local KTool = CS.Engine.Lib.KTool

---@class UIDisasterResponseRankNode
---@field ImgDecorate                   	UnityEngine.RectTransform
---@field TxtDifficulty                 	UnityEngine.RectTransform
---@field SelectGroup                   	UnityEngine.RectTransform
---@field Btn                           	UnityEngine.UI.Button
---@field LockGroup                     	UnityEngine.RectTransform
---@field TxtNumber                     	UnityEngine.RectTransform
---@field ImgComplete                   	UnityEngine.RectTransform
---@field ImgBg                         	Game.Native.Common.UISwitchImage
local UIDisasterResponseRankNode = Class('UIDisasterResponseRankNode')

function UIDisasterResponseRankNode:__init()
end

function UIDisasterResponseRankNode:__delete()
end

function UIDisasterResponseRankNode:Awake()
    self.animator = KTool.GetComponent(self.controller.gameObject, typeof(CS.UnityEngine.Animator))
    SetButtonAction(self.Btn, function()
        if  self:GetClickCB() then
            self:GetClickCB()(self:GetRank(), self:GetRank() <= (self:GetProgress() + 1))
        end
    end)
end

function UIDisasterResponseRankNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end


-------------------------------------------------- get/set
---@return QuestSeniorEquipChapterVo
function UIDisasterResponseRankNode:GetCellDt()
    return checkTable(self._cellDt)
end

function UIDisasterResponseRankNode:GetProgress()
    return checkInt(self._progress)
end

function UIDisasterResponseRankNode:GetRank()
    return self:GetCellDt().regionLevel
end

function UIDisasterResponseRankNode:SetClickCB(handler)
    self._clickCB = handler
end
function UIDisasterResponseRankNode:GetClickCB()
    return self._clickCB
end

-------------------------------------------------- public
function UIDisasterResponseRankNode:RefreshSelf(data, pro, isSelected)
    self._cellDt   = checkTable(data)
    self._progress = checkInt(pro)

    CfUtils.FillText(self.TxtNumber, self:GetRank() < 10 and "0" .. self:GetRank() or self:GetRank())
    KTool.SetActive(self.ImgComplete, self:GetProgress() >= self:GetRank())
    KTool.SetActive(self.LockGroup, self:GetRank() > self:GetProgress() + 1)
    self:RefreshSelectedStatus(isSelected)


    CfUtils.FillImage(self.Btn.transform:Find("ImgQuality"), data.enterIcon)
    CfUtils.FillImage(self.LockGroup.transform:Find("ImgQualityBlack"), data.enterIcon)
end

function UIDisasterResponseRankNode:RefreshSelectedStatus(status)
    local isUnLock = self:GetProgress() >= self:GetRank() - 1
    if not isUnLock then
        CfUtils.SetUISwitchImage(self.ImgBg, 3)
        CfUtils.SetUISwitchText(self.TxtNumber, 3)
        CfUtils.SetUISwitchText(self.TxtDifficulty, 1)
    else
        CfUtils.SetUISwitchText(self.TxtNumber, checkBool(status) and 2 or (isUnLock and 1 or 3))
        CfUtils.SetUISwitchImage(self.ImgBg, checkBool(status) and 2 or (isUnLock and 1 or 3))
        CfUtils.SetUISwitchText(self.TxtDifficulty, checkBool(status) and 2 or 1)
    end
    self.animator:SetInteger("Select", checkBool(status) and 1 or 0)
    --KTool.SetActive(self.ImgDecorate, checkBool(status))
    --KTool.SetActive(self.SelectGroup, true)
    --CfUtils.PlayAnimator(self.controller, checkBool(status) and "Select" or "Open")
end

return UIDisasterResponseRankNode
 
 